COMMON_JS = '''
document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>{let t=document.querySelector('.toast');if(t)t.remove();t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=b.dataset.demo;document.body.append(t);setTimeout(()=>t.remove(),4500)}));
document.querySelectorAll('[data-group]').forEach(group=>group.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{group.querySelectorAll('button').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});b.classList.add('selected');b.setAttribute('aria-pressed','true')})));
'''

def page(filename, title, body, script='', dark=False):
    full = '<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+CSS+'</style><body><div class="demo-strip">Набросок интерфейса · демонстрационные ответы · без отправки данных</div>'
    full += ('<div class="dark">'+HEADER+'</div>' if dark else HEADER)
    full += body + FOOTER + '<script>' + COMMON_JS + script + '</script></body></html>'
    (OUT / filename).write_text(full, encoding='utf-8')

