body1 = '''<main id="main"><div class="dark"><div class="wrap"><div class="crumb">Малому бизнесу и ИП / Кредиты / Умный подбор</div><section class="hero split"><div><div class="eyebrow">01 / Подбор с сопровождением</div><h1>Кредит под вашу<br>бизнес-задачу</h1><p class="lead">Расскажите, на что нужны деньги.<br>Поможем разобраться в решениях<br>для малого и микробизнеса.</p><div class="tags"><span class="tag gray">Для ИП и ООО</span><span class="tag gray">С объяснением выбора</span></div><img class="art smallart" src="'''+briefcase+'''" alt="Объемный красный бизнес-портфель с диаграммой"></div><div class="panel" id="wizard"><div class="pill-row"><b>Подберём решение вместе</b><span class="step-info" id="stepLabel">Шаг 1 из 4</span></div><div class="progress"><i id="bar"></i></div><h3 id="question">На что нужны деньги?</h3><p class="muted small" id="questionHint">Выберите ближайшую задачу.</p><div class="options" id="answers"></div><div class="actions"><button class="btn secondary" id="prev" disabled>Назад</button><button class="btn" id="next" disabled>Далее →</button></div><p class="note">Сначала подбор. Данные для заявки — после выбора решения.</p></div></section></div></div><div class="white-curve">'''+HOW+'''<section class="section wrap"><h2>Вы увидите логику рекомендации</h2><div class="grid2" style="margin-top:28px"><article class="card blue"><h3>Почему подходит</h3><p>Свяжем способ финансирования с вашей задачей: разовая покупка или регулярные расходы.</p></article><article class="card blue"><h3>Что ещё рассмотреть</h3><p>Покажем альтернативу и объясним, в каком случае она удобнее.</p></article></div></section>'''+FAQ+'''</div></main>'''
js1 = '''
const steps=[{q:'На что нужны деньги?',hint:'Выберите ближайшую задачу.',a:['Закупить товар','Купить оборудование','Покрыть кассовый разрыв','Другая задача']},{q:'Как удобнее получить деньги?',hint:'Это поможет выбрать формат финансирования.',a:['Одной суммой','Частями по мере необходимости']},{q:'На какой срок планируете?',hint:'Ориентир для подбора, а не условие банка.',a:['До года','От года до трёх лет','Пока не знаю']},{q:'Что для вас важнее?',hint:'Выберите основной приоритет.',a:['Предсказуемый график','Гибкость использования','Хочу сравнить варианты']}];let step=0,answers=[];
function renderWizard(){const done=step===4;document.getElementById('stepLabel').textContent=done?'Готово':'Шаг '+(step+1)+' из 4';document.getElementById('bar').style.width=(done?100:(step+1)*25)+'%';document.getElementById('prev').disabled=step===0;document.getElementById('next').hidden=done;const box=document.getElementById('answers');box.replaceChildren();if(done){const flex=answers[1]===1;document.getElementById('question').textContent=flex?'Рассмотрите кредитную линию':'Рассмотрите кредит одной суммой';document.getElementById('questionHint').textContent='Пример логики подбора, без проверки доступности.';box.innerHTML='<div class="outcome"><b>Почему это может подойти</b><p>Вы выбрали '+(flex?'получение денег частями. Такой формат можно рассмотреть для повторяющихся расходов.':'получение всей суммы сразу. Такой формат можно рассмотреть для разовой задачи.')+'</p><p class="small">Сумма, ставка и срок: [условия банка]</p><div class="actions"><button class="btn" id="demoApply">Перейти к заявке</button></div></div>';document.getElementById('demoApply').onclick=()=>{document.getElementById('questionHint').textContent='Демонстрация: в рабочем сервисе здесь откроется заявка с выбранными параметрами.'};return}document.getElementById('question').textContent=steps[step].q;document.getElementById('questionHint').textContent=steps[step].hint;document.getElementById('next').disabled=answers[step]===undefined;steps[step].a.forEach((a,i)=>{const b=document.createElement('button');b.className='answer'+(answers[step]===i?' selected':'');b.setAttribute('aria-pressed',answers[step]===i);b.innerHTML='<b>'+a+'</b><span>'+(answers[step]===i?'●':'○')+'</span>';b.onclick=()=>{answers[step]=i;renderWizard()};box.append(b)})}document.getElementById('prev').onclick=()=>{step--;renderWizard()};document.getElementById('next').onclick=()=>{step++;renderWizard()};renderWizard();
'''
