body2 = '''<main id="main"><div class="wrap"><div class="crumb">Малому бизнесу и ИП / Кредиты / Умный подбор</div><section class="hero"><div class="eyebrow">02 / Сначала цифры</div><div class="section-head"><h1>Какая сумма<br>поможет вашему делу?</h1><p class="muted">Задайте параметры —<br>сравните способы финансирования.</p></div><div class="card" style="margin-top:36px"><div class="split"><div><h3>Параметры вашей задачи</h3><label class="field"><span>Нужная сумма · демонстрационный ввод</span><input id="amount" type="number" min="100000" max="10000000" step="100000" value="1500000" aria-label="Нужная сумма в рублях"><input id="amountRange" type="range" min="100000" max="10000000" step="100000" value="1500000" aria-label="Изменить сумму ползунком"></label><div class="row small muted"><span>100 тыс. ₽</span><span>10 млн ₽</span></div><p class="small muted">Диапазон нужен для демонстрации интерфейса.</p><label class="field"><span>Желаемый срок</span><select id="term"><option value="12">12 месяцев</option><option value="24" selected>24 месяца</option><option value="36">36 месяцев</option></select></label><p class="small" style="margin-top:24px">Как получать деньги?</p><div class="chips" data-group id="format"><button class="chip selected" aria-pressed="true">Одной суммой</button><button class="chip" aria-pressed="false">Частями</button></div></div><article class="panel"><span class="tag green">Предварительный подбор</span><h2 class="result-title" id="calcProduct">Кредит одной суммой</h2><p class="muted small" id="calcWhy">Для разовой задачи, когда вся сумма нужна сразу.</p><div class="divider"></div><div class="row"><span class="muted">Ваш запрос</span><b id="amountOut">1 500 000 ₽</b></div><div class="row"><span class="muted">Желаемый срок</span><b id="termOut">24 месяца</b></div><div class="row"><span class="muted">Ставка</span><b>[ставка банка]</b></div><div class="row"><span class="muted">Платёж в месяц</span><b>[после расчёта]</b></div><div class="actions"><a class="btn full" href="#alternatives">Сравнить решения ↓</a></div><p class="note">Платёж появится после подключения тарифов банка. Допуслуги и комиссии должны учитываться в расчёте.</p></article></div></div></section><section class="section" id="alternatives"><div class="section-head"><h2>Два способа решить задачу</h2><span class="tag gray">Пример сравнения форматов</span></div><div class="grid2"><article class="card blue"><h3>Кредит одной суммой</h3><p>Рассмотрите для разовой закупки или покупки оборудования.</p><div class="bullet"><span class="check">✓</span>Вся сумма для одной задачи</div><div class="bullet"><span class="check">✓</span>График погашения по договору</div><div class="actions"><button class="btn" data-demo="Выбран кредит одной суммой. Дальше — заявка для проверки условий банком.">Выбрать формат</button></div></article><article class="card"><h3>Кредитная линия</h3><p>Рассмотрите, если финансирование требуется периодически.</p><div class="bullet"><span class="check">✓</span>Получение денег частями</div><div class="bullet"><span class="check">✓</span>Параметры использования по договору</div><div class="actions"><button class="btn secondary" data-demo="Выбрана кредитная линия. Дальше — заявка для проверки условий банком.">Рассмотреть вариант</button></div></article></div></section></div>'''+HOW+FAQ+'''</main>'''
js2 = '''const amount=document.getElementById('amount'),range=document.getElementById('amountRange'),term=document.getElementById('term');function calc(){document.getElementById('amountOut').textContent=Number(amount.value).toLocaleString('ru-RU')+' ₽';document.getElementById('termOut').textContent=term.options[term.selectedIndex].text}amount.oninput=()=>{range.value=amount.value;calc()};range.oninput=()=>{amount.value=range.value;calc()};term.onchange=calc;document.querySelectorAll('#format button').forEach((b,i)=>b.addEventListener('click',()=>{document.getElementById('calcProduct').textContent=i?'Кредитная линия':'Кредит одной суммой';document.getElementById('calcWhy').textContent=i?'Для задач, которые возникают в разное время.':'Для разовой задачи, когда вся сумма нужна сразу.'}));calc();'''
