body3 = '''<main id="main"><div style="background:#ffcf99"><div class="wrap"><div class="crumb">Малому бизнесу и ИП / Умный подбор кредита</div><section class="hero split wide-left"><div><div class="eyebrow">03 / От задачи бизнеса</div><h1>У каждого дела<br>свой следующий шаг</h1><p class="lead">Выберите, что хотите сделать.<br>Подскажем, какой формат кредита<br>стоит рассмотреть.</p><div class="actions"><a class="btn" href="#tasks">Выбрать задачу ↓</a></div></div><img class="art" src="'''+growth+'''" alt="Объемная диаграмма роста с красной стрелкой"></section></div></div><div class="white-curve"><section class="section wrap" id="tasks"><div class="section-head"><h2>На что нужны деньги?</h2><p class="muted">Начнём с понятной задачи.<br>Термины разберём по ходу.</p></div><div class="grid3" id="taskGrid"><button class="choice-card selected" style="background:#e4f0ff" data-task="Закупить товар" aria-pressed="true"><span class="glyph" aria-hidden="true">▦</span><h3>Закупить товар</h3><p>Для магазина или маркетплейса</p><span class="arrow">↗</span></button><button class="choice-card" style="background:#f1e7ff" data-task="Купить оборудование" aria-pressed="false"><span class="glyph" aria-hidden="true">⚙</span><h3>Купить оборудование</h3><p>Запустить или расширить дело</p><span class="arrow">↗</span></button><button class="choice-card" style="background:#effcc6" data-task="Покрыть разрыв" aria-pressed="false"><span class="glyph" aria-hidden="true">⇄</span><h3>Покрыть разрыв</h3><p>Когда расходы раньше выручки</p><span class="arrow">↗</span></button></div><div class="card" style="margin-top:28px"><div class="split"><div><span class="eyebrow">Ваша задача</span><h2 id="taskTitle">Закупить товар</h2><p class="muted" id="taskDescription">Одна большая закупка или регулярное пополнение? От этого зависит формат финансирования.</p><div class="chips" data-group id="taskFormat"><button class="chip selected" aria-pressed="true">Одна закупка</button><button class="chip" aria-pressed="false">Регулярные расходы</button></div></div><article class="panel"><span class="tag">Можно рассмотреть</span><h3 style="margin-top:16px" id="taskProduct">Кредит одной суммой</h3><p class="small muted" id="taskReason">Вся сумма нужна сразу — под конкретную закупку.</p><div class="divider"></div><div class="row small"><span>Условия</span><b>[предложение банка]</b></div><button class="btn full" style="margin-top:24px" data-demo="В рабочем подборе следующий шаг уточнит сумму, срок и данные бизнеса.">Уточнить параметры →</button></article></div></div></section>'''+HOW+FAQ+'''</div></main>'''
js3 = '''let task=0,regular=false;const descriptions=['Одна большая закупка или регулярное пополнение? От этого зависит формат финансирования.','Планируете одну покупку или обновляете оборудование поэтапно? Уточним способ получения денег.','Нужно закрыть один разрыв или расходы регулярно опережают поступления? Рассмотрим оба сценария.'];function taskUpdate(){document.getElementById('taskProduct').textContent=regular?'Кредитная линия':'Кредит одной суммой';document.getElementById('taskReason').textContent=regular?'Деньги могут понадобиться в разное время. Рассмотрите получение частями.':['Вся сумма нужна сразу — под конкретную закупку.','Вся сумма нужна для одной покупки оборудования.','Деньги нужны однократно, чтобы покрыть конкретные расходы.'][task]}document.querySelectorAll('#taskGrid button').forEach((b,i)=>b.onclick=()=>{task=i;document.querySelectorAll('#taskGrid button').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});b.classList.add('selected');b.setAttribute('aria-pressed','true');document.getElementById('taskTitle').textContent=b.dataset.task;document.getElementById('taskDescription').textContent=descriptions[i];taskUpdate()});document.querySelectorAll('#taskFormat button').forEach((b,i)=>b.addEventListener('click',()=>{regular=!!i;taskUpdate()}));'''
page('alfa-credit-03-business-goals.html','03 · От задачи бизнеса',body3,js3)

body4 = '''<main id="main" class="wrap"><div class="crumb">Малому бизнесу и ИП / Кредиты / Помощник</div><section class="hero"><div class="section-head"><div><div class="eyebrow">04 / Подбор в диалоге</div><h1>Давайте разберёмся,<br>что подойдёт вашему делу</h1></div><p class="muted">По одному вопросу.<br>С понятным итогом.</p></div><div class="chat-shell" style="margin-top:32px"><aside class="chat-side"><b>Ваш подбор</b><ul><li class="current" id="chatStep1">01 &nbsp; Задача бизнеса</li><li id="chatStep2">02 &nbsp; Получение денег</li><li id="chatStep3">03 &nbsp; Решение</li></ul><div class="divider"></div><p class="small muted">Можно вернуться к началу<br>и изменить ответы.</p><button class="chip" id="resetChat" style="margin-top:18px">Начать заново</button></aside><div class="chat-main"><div class="pill-row"><b>Помощник по кредитам</b><span class="tag gray">Демо-диалог</span></div><div class="divider"></div><div id="messages" role="log" aria-live="polite"></div><div class="chips" id="chatChoices"></div></div></div><p class="note">Это управляемый сценарий прототипа. Рабочий помощник должен опираться на проверенные данные банка и объяснять основания рекомендации.</p></section><section class="section" id="how"><div class="grid3"><article class="card blue"><h3>Без сложной анкеты</h3><p>Один вопрос за раз и быстрые варианты ответа.</p></article><article class="card"><h3>Ваши ответы рядом</h3><p>В диалоге видно, из чего сложилась рекомендация.</p></article><article class="card"><h3>Решение с объяснением</h3><p>Помощник связывает задачу и формат финансирования.</p></article></div></section>'''+FAQ+'''</main>'''
js4 = '''let chatStep=0,chatTask='',chatFlexible=false;const messages=document.getElementById('messages'),choices=document.getElementById('chatChoices');function bubble(text,user=false){const b=document.createElement('div');b.className='bubble'+(user?' user':'');b.textContent=text;messages.append(b)}function choose(items,callback){choices.replaceChildren();items.forEach(t=>{const b=document.createElement('button');b.className='chip';b.textContent=t;b.onclick=()=>callback(t);choices.append(b)})}function resetChat(){chatStep=0;messages.replaceChildren();bubble('Здравствуйте! Какую задачу бизнеса вы хотите решить с помощью кредита?');choose(['Закупить товар','Купить оборудование','Покрыть кассовый разрыв'],pickTask);document.querySelectorAll('.chat-side li').forEach((x,i)=>x.classList.toggle('current',i===0))}function pickTask(t){chatTask=t;bubble(t,true);bubble('Деньги нужны сразу или удобнее получать их частями?');choose(['Вся сумма сразу','Частями'],pickFormat);document.getElementById('chatStep2').classList.add('current')}function pickFormat(t){chatFlexible=t==='Частями';bubble(t,true);bubble(chatFlexible?'Вы выбрали получение денег частями. Для такой задачи стоит рассмотреть кредитную линию.':'Вы выбрали получение всей суммы сразу. Для такой задачи стоит рассмотреть кредит одной суммой.');const c=document.createElement('div');c.className='outcome';c.innerHTML='<span class="tag">Пример рекомендации</span><h3 style="margin-top:14px">'+(chatFlexible?'Кредитная линия':'Кредит одной суммой')+'</h3><p class="small">Задача: '+chatTask.toLowerCase()+'.</p><p class="small muted">Ставка и доступность: [после проверки банком]</p>';messages.append(c);choose(['Начать заново','Перейти к параметрам'],t=>{if(t==='Начать заново')resetChat();else{choices.replaceChildren();bubble('Следующий шаг рабочего сервиса — уточнение суммы и срока перед заявкой. В этом наброске данные не отправляются.')}});document.getElementById('chatStep3').classList.add('current')}document.getElementById('resetChat').onclick=resetChat;resetChat();'''
page('alfa-credit-04-assistant.html','04 · Подбор в диалоге',body4,js4)

body5 = '''<main id="main" class="dashboard"><div class="wrap"><div class="crumb">Малому бизнесу и ИП / Кредиты / Сравнение решений</div><section class="hero"><div class="eyebrow">05 / Прозрачное сравнение</div><h1>Выберите решение.<br>Понимая разницу.</h1><p class="lead">Ваши параметры слева. Подходящие форматы — справа.<br>Причины выбора — в каждой рекомендации.</p></section><section class="section" style="padding-top:0" id="how"><div class="sidebar-layout"><aside class="card white"><h3>Ваша задача</h3><label class="field"><span>Цель финансирования</span><select id="compareGoal" style="font-size:16px"><option>Закупить товар</option><option>Купить оборудование</option><option>Кассовый разрыв</option></select></label><label class="field"><span>Желаемая сумма · демо</span><input id="compareAmount" type="number" value="1500000" min="100000" step="100000" style="font-size:18px"></label><p class="small" style="margin-top:24px">Способ получения</p><div class="options" id="compareFormat"><button class="answer selected" aria-pressed="true" data-index="0">Вся сумма сразу</button><button class="answer" aria-pressed="false" data-index="1">Частями</button></div><p class="note">Параметры меняют порядок форматов в демо. Доступность проверит банк.</p></aside><div><div class="pill-row" style="margin-bottom:18px"><b>Два формата для сравнения</b><span class="small muted">Без проверки одобрения</span></div><div id="compareCards"></div><article class="card white" style="margin-top:20px"><h3>Сравнить по главным отличиям</h3><table class="comparison"><thead><tr><th scope="col">Параметр</th><th scope="col">Одной суммой</th><th scope="col">Кредитная линия</th></tr></thead><tbody><tr><th scope="row">Получение</th><td>Вся сумма сразу</td><td>Частями в пределах лимита</td></tr><tr><th scope="row">Сценарий</th><td>Разовая задача</td><td>Повторяющиеся расходы</td></tr><tr><th scope="row">Ставка</th><td>[условия банка]</td><td>[условия банка]</td></tr><tr><th scope="row">Погашение</th><td>[по договору]</td><td>[по договору]</td></tr></tbody></table><p class="note">Сравнение описывает концепцию подачи. Конкретные возможности каждого продукта необходимо подтвердить по его условиям.</p></article></div></div></section>'''+FAQ+'''</div></main>'''
js5 = '''let format=0;function compareRender(){const products=['Кредит одной суммой','Кредитная линия'];const reasons=['Вы хотите получить всю сумму сразу. Это соответствует разовой задаче.','Вы хотите получать деньги частями. Рассмотрите формат для повторяющихся расходов.'];const list=document.getElementById('compareCards');list.replaceChildren();[format,1-format].forEach((i,k)=>{const c=document.createElement('article');c.className='recommendation';c.style.marginBottom='16px';c.innerHTML='<div><span class="tag '+(!k?'green':'gray')+'">'+(!k?'Ближе к вашему запросу':'Альтернатива')+'</span><h2 class="result-title">'+products[i]+'</h2><p class="small muted">Задача: '+document.getElementById('compareGoal').value.toLowerCase()+'</p><div class="why"><b>Почему рассмотреть</b><p>'+(k?'Подойдёт, если вы измените способ получения денег.':reasons[i])+'</p></div></div><div class="side"><span class="small muted">Ваш запрос</span><div class="metric">'+Number(document.getElementById('compareAmount').value).toLocaleString('ru-RU')+' ₽</div><p class="small muted">Условия: [после проверки]</p><button class="btn '+(k?'secondary':'')+' full" style="margin-top:24px">'+(k?'Подробнее':'Выбрать решение')+'</button></div>';c.querySelector('button').onclick=()=>{c.querySelector('.why').innerHTML='<b>'+products[i]+'</b><p>В рабочем сервисе здесь будут подробные условия и переход к заявке. В демо данные не отправляются.</p>'};list.append(c)})}document.querySelectorAll('#compareFormat button').forEach((b,i)=>b.onclick=()=>{format=i;document.querySelectorAll('#compareFormat button').forEach((x,j)=>{x.classList.toggle('selected',j===i);x.setAttribute('aria-pressed',j===i)});compareRender()});document.getElementById('compareGoal').onchange=compareRender;document.getElementById('compareAmount').oninput=compareRender;compareRender();'''
page('alfa-credit-05-comparison.html','05 · Прозрачное сравнение',body5,js5)

